//! The REST API, on Axum.
//!
//! [`ApiDoc`] is the utoipa `OpenAPI` document,
//! and [`events_routes`] and
//! [`metrics_routes`] are the route
//! tables `App::routes` mounts. Handlers live in
//! [`handlers`], shared services in
//! [`state`]
//! ([`AppState`]).

use utoipa::OpenApi;

pub mod auth;
pub mod handlers;
pub mod routes;
pub mod state;

pub use state::AppState;

