/// Native axa controller routes (idiomatic path): the `/api` surface
/// as an axa `Routes`; handlers extract `AppState` from the `AppContext`
/// shared store via `FromRef`. The root `/metrics.prom` route is [`metrics_routes`].
#[must_use]
pub fn events_routes() -> axa::routes::Routes {
    use axa::prelude::{Routes, get, post};
    Routes::new()
        .prefix("/api")
        .add("/health", get(handlers::health_check))
        .add("/whoami", get(auth::whoami))
        .add("/events", post(handlers::create_event))
        .add(
            "/events/{id}",
            get(handlers::get_event)
                .put(handlers::update_event)
                .delete(handlers::delete_event),
        )
        .add("/events/search", get(handlers::search_events))
        .add("/events/match", post(handlers::match_event))
        .add("/events/check-duplicates", post(handlers::check_duplicates))
        .add("/events/merge", post(handlers::merge_events))
        .add("/events/deduplicate", post(handlers::batch_deduplicate))
        .add("/events/review-queue", get(handlers::get_review_queue))
        .add(
            "/events/review-queue/{id}/decision",
            post(handlers::review_decision),
        )
        .add("/events/{id}/export", get(handlers::export_event_data))
        .add("/events/{id}/masked", get(handlers::get_event_masked))
        .add("/events/{id}/audit", get(handlers::get_event_audit_logs))
        .add("/audit/recent", get(handlers::get_recent_audit_logs))
        // Both registration surfaces carry these: this crate is
        // mid-conversion and a handler added to only one compiles
        // cleanly while serving 404 from the other.
        .add("/records/verify", get(handlers::verify_record_integrity))
        .add("/audit/verify", get(handlers::verify_audit_integrity))
        .add("/audit/user", get(handlers::get_user_audit_logs))
}

/// Root-level Prometheus scrape route (`GET /metrics.prom`).
#[must_use]
pub fn metrics_routes() -> axa::routes::Routes {
    use axa::prelude::{Routes, get};
    Routes::new().add("/metrics.prom", get(handlers::metrics_prom))
}
